const LANG_CODE = { English: 'en', Hindi: 'hi', Telugu: 'te', Tamil: 'ta', Marathi: 'mr' };
const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved && T[saved] ? saved : 'Telugu';
  });

  useEffect(() => {
    if (T[language]) {
      localStorage.setItem(STORAGE_KEY, language);
      document.documentElement.lang = LANG_CODE[language] || 'en';
    }
  }, [language]);

  const t = (k) => T[language]?.[k] ?? T.English[k] ?? k;
  const translateDbValue = (v) => (!v ? '' : DB_MAP[language]?.[v] ?? v);
  const getLocalizedField = (obj, key, fallback = '') => {
    if (!obj) return fallback;
    const code = LANG_CODE[language];
    return (code && obj[`${key}_${code}`]) || obj[key] || fallback;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t, translateDbValue, getLocalizedField }}>
      {children}
    </LanguageContext.Provider>
  );
}

export const useLanguage = () => {
  const ctx = useContext(LanguageContext);
  if (!ctx) throw new Error('useLanguage must be used inside LanguageProvider');
  return ctx;
};